/**
 * admin/seed-chunkbound-survey.mjs
 *
 * Builds the ChunkBound Dev Test feedback survey as a form.
 *
 * Goes through createForm/replaceFields rather than writing rows directly, so
 * the fieldKeys, option lists and per-field config are generated by exactly the
 * same code the dashboard editor uses. Nothing here is a special case.
 *
 *   node admin/seed-chunkbound-survey.mjs              # dry run, changes nothing
 *   node admin/seed-chunkbound-survey.mjs --apply      # create it
 *   node admin/seed-chunkbound-survey.mjs --apply --replace   # overwrite the questions
 *
 * Needs the full .env (the controller layer opens the LuckPerms/QuickShop/
 * LiteBans pools on import), so run it on the deploy host rather than a laptop
 * with a partial config.
 *
 * The form is created CLOSED. Read it through at /dashboard/forms, then tick
 * "Open for submissions" when you are happy with it.
 */

import {
  createForm,
  getFormBySlug,
  replaceFields,
  updateForm,
} from "../controllers/formController.js";

const SLUG = "chunkbound-dev-test-feedback-survey";

const FORM = {
  name: "ChunkBound Dev Test — Feedback Survey",
  slug: SLUG,
  description:
    "Three days of ChunkBound is done, and we want to know how it actually went for you. " +
    "Sixteen questions — most are a single tap, only the last few need any typing.",
  successMessage:
    "Thanks — that is genuinely useful. If you ticked the voice option we will come and find you.",
  // Closed on creation: read it through before anyone can answer it.
  status: false,
  allowMultiple: false,
  // A survey does not want a Discord ticket per response.
  createTicket: false,
  ticketCategoryId: null,
  discordChannelId: null,
  accessCode: null,
  requirements: null,
  reapplyCooldownDays: null,
};

/** `section` rows are page breaks: label is the heading, helpText sits under it. */
const section = (label, helpText = null) => ({ fieldType: "section", label, helpText });

const FIELDS = [
  section("About your run"),
  {
    fieldType: "radio",
    label: "Roughly how long did you play over the three days?",
    isRequired: true,
    options: ["Under an hour", "1–3 hours", "3–8 hours", "8+ hours"],
  },
  {
    fieldType: "checkbox",
    label: "When were you mostly on?",
    helpText: "Pick as many as apply.",
    isRequired: true,
    options: [
      "Saturday evening (the opening)",
      "Sunday",
      "Monday",
      "Tuesday",
      "Late nights / off-peak",
    ],
  },

  section("The big one"),
  {
    fieldType: "scale",
    label: "Would you play the full version at the map reset?",
    isRequired: true,
    config: {
      scaleMin: 1,
      scaleMax: 10,
      scaleMinLabel: "Definitely not",
      scaleMaxLabel: "Absolutely",
    },
  },
  {
    fieldType: "scale",
    label: "How much fun was it, ignoring bugs and balance?",
    isRequired: true,
    config: { scaleMin: 1, scaleMax: 5, scaleMinLabel: "Not much", scaleMaxLabel: "Loads" },
  },

  section("Pacing"),
  {
    fieldType: "radio",
    label: "The first tier — getting out of the opening chunk:",
    isRequired: true,
    options: [
      "Far too slow, it dragged before anything happened",
      "A bit slow",
      "About right",
      "Too quick, barely noticed it",
    ],
  },
  {
    fieldType: "radio",
    label: "Did any single tier drag badly?",
    isRequired: true,
    options: [
      "No, it flowed",
      "Yes, one of the early ones",
      "Yes, one in the middle",
      "Yes, one of the late ones",
      "Yes, more than one",
    ],
  },
  {
    fieldType: "radio",
    label: "Three days as a length:",
    isRequired: true,
    options: ["Too short, wanted more", "About right", "Too long, ran out of steam"],
  },

  section("Contributing"),
  {
    fieldType: "radio",
    label: "Resource costs for tiers were:",
    isRequired: true,
    options: [
      "Way too cheap",
      "A bit cheap",
      "About right",
      "A bit steep",
      "Way too steep",
    ],
  },
  {
    fieldType: "scale",
    label: "Did contributing feel worthwhile — like your turn-ins mattered?",
    isRequired: true,
    config: { scaleMin: 1, scaleMax: 5, scaleMinLabel: "Not really", scaleMaxLabel: "Definitely" },
  },
  {
    fieldType: "scale",
    label: "Was it clear what the server was working toward, and how close it was?",
    isRequired: true,
    config: { scaleMin: 1, scaleMax: 5, scaleMinLabel: "Not at all", scaleMaxLabel: "Very clear" },
  },

  section("The tier stages"),
  {
    fieldType: "radio",
    label: "Which second stage was the most fun?",
    isRequired: true,
    options: [
      "The boss fights",
      "The server-wide challenges",
      "Handing over a Border Shard",
      "They all felt about the same",
      "Didn't see enough of them to say",
    ],
  },
  {
    fieldType: "checkbox",
    label: "Did progress ever stall waiting on something?",
    helpText: "Leave this blank if it never did.",
    isRequired: false,
    options: [
      "Yes — waiting on a Border Shard nobody had",
      "Yes — a boss nobody could kill",
      "Yes — a challenge that couldn't be completed",
      "Yes — just not enough people online",
      "No, it kept moving",
    ],
  },

  section("Dead air"),
  {
    fieldType: "radio",
    label: "Was there ever a stretch with nothing worth doing?",
    isRequired: true,
    options: [
      "Never, always something on",
      "Once or twice, briefly",
      "Fairly often",
      "Most of the time I was on",
    ],
  },

  section("In your own words", "Only these last few need any typing, and none of them are required."),
  {
    fieldType: "text",
    label: "One thing you'd change.",
    maxLength: 200,
    isRequired: false,
  },
  {
    fieldType: "text",
    label: "One thing you'd keep exactly as it is.",
    maxLength: 200,
    isRequired: false,
  },
  {
    fieldType: "textarea",
    label: "Anything broken, odd, or confusing that you noticed?",
    helpText:
      'No need to be precise — "the border did something weird Sunday night" is useful.',
    maxLength: 2000,
    isRequired: false,
  },
  {
    fieldType: "boolean",
    label: "Prefer to talk it through?",
    // `placeholder` is what the tickbox itself reads on the public form.
    placeholder: "I'd rather talk this through in voice than type it",
    helpText: "Tick this and we'll grab you in voice instead.",
    isRequired: false,
  },
];

function summarise() {
  let page = null;
  for (const field of FIELDS) {
    if (field.fieldType === "section") {
      page = field.label;
      console.log(`\n  ${page}`);
      continue;
    }
    const required = field.isRequired ? "required" : "optional";
    console.log(`    - [${field.fieldType}] ${field.label}  (${required})`);
  }
}

async function main() {
  const apply = process.argv.includes("--apply");
  const replace = process.argv.includes("--replace");

  const questions = FIELDS.filter((f) => f.fieldType !== "section").length;
  const pages = FIELDS.filter((f) => f.fieldType === "section").length;

  console.log(`${FORM.name}`);
  console.log(`  ${questions} questions across ${pages} pages, at /forms/${SLUG}`);
  summarise();

  const existing = await getFormBySlug(SLUG);

  if (existing && !replace) {
    console.log(`\nA form already exists at /forms/${SLUG} (formId ${existing.formId}).`);
    console.log("Re-run with --apply --replace to overwrite its questions, or delete it first.");
    console.log("NOTE: replacing the questions orphans the answers already stored against it.");
    return;
  }

  if (!apply) {
    console.log("\nDry run. Re-run with --apply to create it (closed, so nobody can answer yet).");
    return;
  }

  let form;
  if (existing) {
    form = await updateForm(existing.formId, { ...FORM, status: existing.status });
    console.log(`\nUpdated form ${form.formId}.`);
  } else {
    form = await createForm(FORM);
    console.log(`\nCreated form ${form.formId}.`);
  }

  const written = await replaceFields(form.formId, FIELDS);
  console.log(`Wrote ${written} rows (questions plus page breaks).`);
  console.log(`\nReview it at /dashboard/forms/${form.formId}/edit`);
  console.log(`Preview at /forms/${form.slug} — it stays closed until you tick "Open for submissions".`);
}

main()
  .then(() => process.exit(0))
  .catch((error) => {
    console.error("Failed:", error);
    process.exit(1);
  });
